class Solution {
public:
    int numDistinctIslands(vector<vector<int>>& grid) {
        int m = grid.size();
        if (m == 0) {
            return 0;
        }
        int n = grid[0].size();
        set<vector<pair<int, int>>> shapes;
        int dr[4] = {1, -1, 0, 0};
        int dc[4] = {0, 0, 1, -1};
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] != 1) {
                    continue;
                }
                vector<pair<int, int>> shape;
                queue<pair<int, int>> q;
                q.push({r, c});
                grid[r][c] = 0;
                while (!q.empty()) {
                    auto cell = q.front();
                    q.pop();
                    shape.push_back({cell.first - r, cell.second - c});
                    for (int d = 0; d < 4; ++d) {
                        int nr = cell.first + dr[d];
                        int nc = cell.second + dc[d];
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n
                            && grid[nr][nc] == 1) {
                            grid[nr][nc] = 0;
                            q.push({nr, nc});
                        }
                    }
                }
                sort(shape.begin(), shape.end());
                shapes.insert(shape);
            }
        }
        return shapes.size();
    }
};
